                ['date_en' => '1101', 'date_ku' => '1101', 'date_ar' => '1101', 'title_en' => 'The Artuqid capital', 'title_ku' => 'پایتەختی ئەرتوقی', 'title_ar' => 'العاصمة الأرتقية', 'text_en' => 'The Turkmen dynasty rules from the citadel rock; the bridge and the Great Palace follow.', 'text_ku' => 'خانەدانە تورکمانەکە لە بەردی قەڵاوە فەرمانڕەوایی دەکات؛ پرد و کۆشکی گەورە بەدوایدا دێن.', 'text_ar' => 'السلالة التركمانية تحكم من صخرة القلعة؛ ويتبعها الجسر والقصر الكبير.'],
