                ['img' => '07-the-lake-2020', 'alt_en' => 'The flooded Tigris valley at Hasankeyf in 2020, water filling the valley below the cliffs', 'alt_ku' => 'دۆڵی نوقمبووی دیجلە لە حەسەنکێف لە ٢٠٢٠، ئاو دۆڵەکەی خوار زنارەکان پڕ دەکات', 'alt_ar' => 'وادي دجلة المغمور في حسنكيف عام ٢٠٢٠، الماء يملأ الوادي تحت الجروف', 'caption_en' => 'The valley in 2020. The old town lies under the water in the middle distance.', 'caption_ku' => 'دۆڵەکە لە ٢٠٢٠. شاری کۆن لە ژێر ئاوەکەدا لە مەودای ناوەڕاستدا کەوتووە.', 'caption_ar' => 'الوادي عام ٢٠٢٠. ترقد البلدة القديمة تحت الماء في المسافة الوسطى.'],
